const COLS = [
  { headerName: '', field: '__check', checkboxSelection: true, headerCheckboxSelection: true, width: 48, pinned: 'left', sortable: false, filter: false, resizable: false, suppressMenu: true, suppressSizeToFit: true },
  { headerName: 'Code', field: 'code', minWidth: 70, flex: 1 },
  { headerName: 'Name', field: 'name', minWidth: 160, flex: 2 },
  { headerName: 'MTID', field: 'mtid', minWidth: 90, flex: 1 },
  { headerName: 'Service', field: 'service', minWidth: 90, flex: 1 },
  { headerName: 'Rate Criteria', field: 'rate_criteria', minWidth: 160, flex: 2 },
  { headerName: 'Effective Date', field: 'effective_date', minWidth: 110, flex: 1 },
  { headerName: 'Utility', field: 'utility', minWidth: 140, flex: 2 },
  { headerName: 'KWH Range', field: 'kwh_range', minWidth: 100, flex: 1 },
  { headerName: 'KW Range', field: 'kw_range', minWidth: 100, flex: 1 },
  { headerName: 'Customer Count', field: 'customer_count', minWidth: 120, flex: 1 }
];

function normalizeData(model) {
  return Array.isArray(model && model.rows) ? model.rows : [];
}

function rowsSignature(rows) {
  if (!Array.isArray(rows) || rows.length === 0) return "empty";
  return rows.length + "|" + rows[0].masterTariffId + "|" + rows[rows.length - 1].masterTariffId;
}

let gridApi = null;
let lastRowsSig = null;

function emitSelection() {
  if (!gridApi) return;
  const rows = gridApi.getSelectedRows();
  if (appsmith.updateModel) appsmith.updateModel({ selectedRows: rows });
}

function renderGrid(model) {
  const rowData = normalizeData(model);
  const sig = rowsSignature(rowData);
  // Skip rebuild if the underlying rows haven't changed. The model also updates when we
  // write back selectedRows from emitSelection — without this guard, every checkbox click
  // destroys the grid and visually unchecks the row we just clicked.
  if (gridApi && sig === lastRowsSig) return;
  lastRowsSig = sig;
  const gridOptions = {
    columnDefs: COLS,
    rowData,
    rowSelection: 'multiple',
    suppressRowClickSelection: false,
    suppressHorizontalScroll: true,
    pagination: true,
    paginationPageSize: 25,
    paginationPageSizeSelector: [10, 25, 50, 100],
    defaultColDef: {
      sortable: true,
      resizable: true,
      filter: true,
      minWidth: 60,
      menuTabs: ['generalMenuTab', 'filterMenuTab', 'columnsMenuTab']
    },
    animateRows: true,
    popupParent: document.body,
    getRowId: p => String(p.data.masterTariffId),
    onGridReady: params => { gridApi = params.api; },
    onSelectionChanged: emitSelection
  };
  const gridDiv = document.querySelector('#myGrid');
  if (!gridDiv) return;
  gridDiv.innerHTML = '';
  gridApi = agGrid.createGrid(gridDiv, gridOptions);
}

appsmith.onReady(() => {
  renderGrid(appsmith.model);
  appsmith.onModelChange(renderGrid);
});

